            except (KeyError, TypeError, ValueError):
                pass
        if "value" in entry and entry["value"] is not None:
            try:
                return float(entry["value"])
            except (TypeError, ValueError):
                pass
    if indicator and entries:
        return _meta_indicator_value(entries, "")
    return None


